window.DEUTSCH_A1 = {"version":1,"units":[{"id":"a1-01","number":1,"title":"Alphabet & spelling","group":"Foundations","grammar":{"title":"Letters, umlauts and ß","en":"German has 26 basic letters plus Ä, Ö, Ü and ß. Spell names one letter at a time. ß sounds like ss.","ne":"जर्मनमा Ä, Ö, Ü र ß पनि प्रयोग हुन्छन्।","example":"Wie schreibt man das?","exampleEn":"How do you spell that?","exampleNe":"त्यसलाई कसरी लेखिन्छ?","pronEnglish":"vee SHRAIBT man das","pronNepali":"वी श्राइब्ट मान दास"},"vocab":[{"de":"A","en":"A","ne":"आ"},{"de":"B","en":"B","ne":"बे"},{"de":"C","en":"C","ne":"त्से"},{"de":"Ä","en":"A-umlaut","ne":"उम्लाउट ए"},{"de":"Ö","en":"O-umlaut","ne":"उम्लाउट ओ"},{"de":"Ü","en":"U-umlaut","ne":"उम्लाउट यू"},{"de":"Buchstabieren","en":"to spell","ne":"हिज्जे गर्नु"}],"reading":{"text":"Ich heiße Lea. Mein Name beginnt mit L.","question":"Which letter does the name start with?","choices":["B","L","M"],"answer":1},"listening":{"text":"Wie heißt du? – Ich heiße Tom. T-O-M.","question":"Which is the correct spelling?","choices":["T-A-M","D-O-M","T-O-M"],"answer":2},"writing":{"prompt":"Write your name and spell it in German letters.","model":"Ich heiße Mina. M-I-N-A."},"speaking":{"prompt":"Say your name, then spell it slowly.","model":"Ich heiße Ravi. R-A-V-I."}},{"id":"a1-02","number":2,"title":"Greetings & politeness","group":"Foundations","grammar":{"title":"Formal and informal greetings","en":"Use Hallo with friends, Guten Tag in many formal daytime settings, and Auf Wiedersehen for a polite goodbye.","ne":"साथीलाई Hallo, औपचारिक भेटमा Guten Tag प्रयोग गर्न सकिन्छ।","example":"Guten Tag! Wie geht es Ihnen?","exampleEn":"Good day! How are you (formal)?","exampleNe":"नमस्कार! तपाईंलाई कस्तो छ?","pronEnglish":"GOO-ten tahk vee gayt ess EE-nen","pronNepali":"गूटन टाक वी गेट एस ईनेन"},"vocab":[{"de":"Hallo","en":"hello","ne":"नमस्ते"},{"de":"Guten Morgen","en":"good morning","ne":"शुभ प्रभात"},{"de":"Guten Tag","en":"good day","ne":"नमस्कार"},{"de":"Guten Abend","en":"good evening","ne":"शुभ साँझ"},{"de":"Tschüss","en":"bye","ne":"बाइ"},{"de":"Danke","en":"thank you","ne":"धन्यवाद"},{"de":"Bitte","en":"please / you are welcome","ne":"कृपया / स्वागत छ"}],"reading":{"text":"Herr Weber kommt um neun Uhr ins Büro. Er sagt: Guten Morgen!","question":"When does he arrive?","choices":["At six","At eight","At nine"],"answer":2},"listening":{"text":"Guten Abend, Frau Koch! – Guten Abend!","question":"Which greeting was used?","choices":["Good evening","Good morning","Good night"],"answer":0},"writing":{"prompt":"Write a polite greeting and goodbye to a teacher.","model":"Guten Tag, Frau Müller! Auf Wiedersehen!"},"speaking":{"prompt":"Greet a friend, then a teacher.","model":"Hallo, Anna! Guten Tag, Frau Braun!"}},{"id":"a1-03","number":3,"title":"Introducing yourself","group":"Foundations","grammar":{"title":"Ich heiße / Ich bin","en":"Use ich heiße + name or ich bin + name. Introduce yourself with name and a simple fact.","ne":"आफ्नो नाम बताउन ich heiße वा ich bin प्रयोग गर्नुहोस्।","example":"Ich heiße Sita und ich bin Studentin.","exampleEn":"My name is Sita and I am a student.","exampleNe":"मेरो नाम सीता हो र म विद्यार्थी हुँ।","pronEnglish":"ikh HAI-suh ZEE-tah unt ikh bin shtoo-DEN-tin","pronNepali":"इख हाइसे सीता उन्ट इख बिन श्टुडेन्टिन"},"vocab":[{"de":"ich","en":"I","ne":"म"},{"de":"du","en":"you (informal)","ne":"तिमी"},{"de":"Sie","en":"you (formal)","ne":"तपाईं"},{"de":"heißen","en":"to be called","ne":"नाम हुनु"},{"de":"der Name","en":"name","ne":"नाम"},{"de":"der Vorname","en":"first name","ne":"पहिलो नाम"},{"de":"der Nachname","en":"surname","ne":"थर"}],"reading":{"text":"Hallo! Ich bin Omar. Mein Nachname ist Ali.","question":"What is the surname?","choices":["Ali","Omar","Hallo"],"answer":0},"listening":{"text":"Guten Tag. Ich heiße Sara. Wie heißen Sie?","question":"What is the speaker asking?","choices":["Your job","Your name","Your address"],"answer":1},"writing":{"prompt":"Write three sentences introducing yourself.","model":"Ich heiße Nisha. Ich komme aus Nepal. Ich lerne Deutsch."},"speaking":{"prompt":"Introduce yourself with your name and one fact.","model":"Ich heiße Bivek. Ich komme aus Nepal."}},{"id":"a1-04","number":4,"title":"Countries & languages","group":"Foundations","grammar":{"title":"kommen aus + country","en":"Use ich komme aus Nepal, ich wohne in Berlin, and ich spreche Deutsch. Some countries take an article.","ne":"म कहाँबाट आएको हुँ: ich komme aus Nepal।","example":"Ich komme aus Nepal und spreche Nepali.","exampleEn":"I come from Nepal and speak Nepali.","exampleNe":"म नेपालबाट आएको हुँ र नेपाली बोल्छु।","pronEnglish":"ikh KOM-uh owss neh-PAHL","pronNepali":"इख कोमे आउस नेपाल"},"vocab":[{"de":"das Land","en":"country","ne":"देश"},{"de":"Nepal","en":"Nepal","ne":"नेपाल"},{"de":"Deutschland","en":"Germany","ne":"जर्मनी"},{"de":"Indien","en":"India","ne":"भारत"},{"de":"sprechen","en":"to speak","ne":"बोल्नु"},{"de":"wohnen","en":"to live","ne":"बस्नु"},{"de":"Deutsch","en":"German","ne":"जर्मन"},{"de":"Englisch","en":"English","ne":"अङ्ग्रेजी"}],"reading":{"text":"Lina wohnt in München. Sie kommt aus Indien.","question":"Where does Lina come from?","choices":["Germany","India","Nepal"],"answer":1},"listening":{"text":"Ich komme aus Spanien, aber ich wohne in Deutschland.","question":"Where does the speaker live?","choices":["Spain","Austria","Germany"],"answer":2},"writing":{"prompt":"Write your home country, current town and language.","model":"Ich komme aus Nepal. Ich wohne in Kathmandu. Ich spreche Nepali."},"speaking":{"prompt":"Answer: Woher kommen Sie? Welche Sprachen sprechen Sie?","model":"Ich komme aus Nepal. Ich spreche Nepali und Englisch."}},{"id":"a1-05","number":5,"title":"Numbers & phone numbers","group":"Foundations","grammar":{"title":"Numbers 0–100","en":"In German, 21 is einundzwanzig (one-and-twenty). Phone numbers are often spoken digit by digit.","ne":"जर्मनमा २१ लाई einundzwanzig भनिन्छ।","example":"Meine Telefonnummer ist null eins sieben zwei.","exampleEn":"My phone number is zero one seven two.","exampleNe":"मेरो फोन नम्बर शून्य एक सात दुई हो।","pronEnglish":"MAI-nuh teh-leh-FOHN-noom-er ist nool ains ZEE-ben tsvai","pronNepali":"माइने टेलेफोन नुमर इस्ट नुल आइन्स जीबन त्स्वाइ"},"vocab":[{"de":"null","en":"zero","ne":"शून्य"},{"de":"eins","en":"one","ne":"एक"},{"de":"zwei","en":"two","ne":"दुई"},{"de":"drei","en":"three","ne":"तीन"},{"de":"zehn","en":"ten","ne":"दश"},{"de":"zwanzig","en":"twenty","ne":"बीस"},{"de":"dreißig","en":"thirty","ne":"तीस"},{"de":"hundert","en":"hundred","ne":"सय"}],"reading":{"text":"Der Kurs kostet zwanzig Euro. Die Prüfung kostet dreißig Euro.","question":"How much does the course cost?","choices":["30 euros","10 euros","20 euros"],"answer":2},"listening":{"text":"Das Ticket kostet zwölf Euro. Bitte bezahlen Sie an der Kasse.","question":"What is the ticket price?","choices":["12 euros","20 euros","2 euros"],"answer":0},"writing":{"prompt":"Write a price and a telephone number in German words.","model":"Das Buch kostet zehn Euro. Meine Nummer ist eins zwei drei."},"speaking":{"prompt":"Say the numbers 0 to 10 and your telephone number slowly.","model":"Null, eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn."}},{"id":"a1-06","number":6,"title":"Clock, weekdays & dates","group":"Foundations","grammar":{"title":"um / am / im","en":"Use um for clock time, am for days and dates, im for months and seasons.","ne":"घडीको समयमा um, दिनमा am, महिनामा im प्रयोग हुन्छ।","example":"Der Termin ist am Montag um zehn Uhr.","exampleEn":"The appointment is on Monday at ten.","exampleNe":"भेटघाट सोमबार दस बजे छ।","pronEnglish":"dehr tehr-MEEN ist am MOHN-tahk oom tsehn oor","pronNepali":"देर टेर्मिन इस्ट आम मोन्टाक उम त्सेन उर"},"vocab":[{"de":"die Uhr","en":"clock / o’clock","ne":"घडी / बजे"},{"de":"heute","en":"today","ne":"आज"},{"de":"morgen","en":"tomorrow","ne":"भोलि"},{"de":"Montag","en":"Monday","ne":"सोमबार"},{"de":"Freitag","en":"Friday","ne":"शुक्रबार"},{"de":"Januar","en":"January","ne":"जनवरी"},{"de":"der Termin","en":"appointment","ne":"भेटघाट"},{"de":"die Woche","en":"week","ne":"हप्ता"}],"reading":{"text":"Die Bibliothek öffnet am Montag um neun Uhr. Am Sonntag ist sie zu.","question":"When is it closed?","choices":["Sunday","Monday","Friday"],"answer":0},"listening":{"text":"Unser Treffen ist am Freitag um vierzehn Uhr.","question":"Which day is the meeting?","choices":["Monday","Friday","Tuesday"],"answer":1},"writing":{"prompt":"Write an appointment message with a day and time.","model":"Hallo Ali, unser Termin ist am Dienstag um 10 Uhr. Bis dann!"},"speaking":{"prompt":"Say today’s weekday and an appointment time.","model":"Heute ist Montag. Mein Termin ist um neun Uhr."}},{"id":"a1-07","number":7,"title":"Family & relationships","group":"People & home","grammar":{"title":"mein / meine","en":"Use mein before many masculine and neuter singular nouns; meine before feminine and plural nouns in the basic subject form.","ne":"साधारण कर्ता रूपमा der/das सँग mein र die/बहुवचनसँग meine।","example":"Das ist meine Mutter und das ist mein Vater.","exampleEn":"This is my mother and this is my father.","exampleNe":"यो मेरी आमा र यो मेरा बुबा हुन्।","pronEnglish":"das ist MAI-nuh MOOT-er unt das ist main FAH-ter","pronNepali":"दास इस्ट माइने मुटर उन्ट दास इस्ट माइन फाटर"},"vocab":[{"de":"die Mutter","en":"mother","ne":"आमा"},{"de":"der Vater","en":"father","ne":"बुबा"},{"de":"die Schwester","en":"sister","ne":"दिदी / बहिनी"},{"de":"der Bruder","en":"brother","ne":"दाइ / भाइ"},{"de":"die Eltern","en":"parents","ne":"आमाबुबा"},{"de":"das Kind","en":"child","ne":"बच्चा"},{"de":"die Familie","en":"family","ne":"परिवार"}],"reading":{"text":"Mein Bruder heißt Jan. Meine Schwester heißt Eva.","question":"Who is Eva?","choices":["The brother","The sister","The mother"],"answer":1},"listening":{"text":"Das ist mein Sohn Leo. Er ist drei Jahre alt.","question":"How old is Leo?","choices":["Ten","Seven","Three"],"answer":2},"writing":{"prompt":"Write four sentences about your family.","model":"Meine Familie ist klein. Meine Mutter heißt Sita. Mein Vater heißt Ram. Ich habe einen Bruder."},"speaking":{"prompt":"Tell someone who is in your family.","model":"Ich habe eine Schwester und einen Bruder."}},{"id":"a1-08","number":8,"title":"People, ages & descriptions","group":"People & home","grammar":{"title":"er / sie / es; sein","en":"Use er for he, sie for she, and es for it. Sein changes: ich bin, du bist, er/sie ist.","ne":"er=ऊ पुरुष, sie=ऊ महिला, es=यो; ich bin, du bist, sie ist।","example":"Meine Schwester ist zwanzig Jahre alt.","exampleEn":"My sister is twenty years old.","exampleNe":"मेरी बहिनी बीस वर्षकी छिन्।","pronEnglish":"MAI-nuh SHVES-ter ist TSVAN-tsikh YAH-ruh alt","pronNepali":"माइने श्वेस्टर इस्ट त्स्वान्सिख यारे आल्ट"},"vocab":[{"de":"jung","en":"young","ne":"जवान"},{"de":"alt","en":"old","ne":"वृद्ध / पुरानो"},{"de":"groß","en":"tall / big","ne":"अग्लो / ठूलो"},{"de":"klein","en":"small","ne":"सानो"},{"de":"freundlich","en":"friendly","ne":"मिलनसार"},{"de":"das Alter","en":"age","ne":"उमेर"},{"de":"das Jahr","en":"year","ne":"वर्ष"}],"reading":{"text":"Erik ist 28 Jahre alt. Seine Schwester ist 25.","question":"How old is Erik?","choices":["25","18","28"],"answer":2},"listening":{"text":"Mein Vater ist sechzig Jahre alt und sehr freundlich.","question":"Who is friendly?","choices":["The father","The sister","The teacher"],"answer":0},"writing":{"prompt":"Write a basic description of a person.","model":"Meine Freundin heißt Lena. Sie ist 23 Jahre alt. Sie ist freundlich."},"speaking":{"prompt":"Say your age and describe a friend.","model":"Ich bin 25 Jahre alt. Mein Freund ist groß und freundlich."}},{"id":"a1-09","number":9,"title":"Jobs & studying","group":"People & home","grammar":{"title":"arbeiten als / studieren","en":"Use ich arbeite als + profession, or ich studiere + subject. Ich lerne Deutsch means I learn German.","ne":"पेशा बताउँदा ich arbeite als ... प्रयोग गर्नुहोस्।","example":"Ich arbeite als Entwickler und lerne Deutsch.","exampleEn":"I work as a developer and learn German.","exampleNe":"म विकासकर्ताको रूपमा काम गर्छु र जर्मन सिक्छु।","pronEnglish":"ikh AR-bai-tuh als ent-VIK-ler unt LEHR-nuh DOITCH","pronNepali":"इख आरबाइटे आल्स एन्टभिक्लर उन्ट लेर्ने डोइच"},"vocab":[{"de":"der Beruf","en":"profession","ne":"पेशा"},{"de":"arbeiten","en":"to work","ne":"काम गर्नु"},{"de":"studieren","en":"to study at university","ne":"विश्वविद्यालयमा पढ्नु"},{"de":"lernen","en":"to learn","ne":"सिक्नु"},{"de":"der Lehrer","en":"teacher (male)","ne":"शिक्षक"},{"de":"die Ärztin","en":"doctor (female)","ne":"चिकित्सक"},{"de":"der Student","en":"university student (male)","ne":"विद्यार्थी"}],"reading":{"text":"Mia studiert Informatik. Am Abend lernt sie Deutsch.","question":"What does Mia study?","choices":["Computer science","Medicine","Music"],"answer":0},"listening":{"text":"Ich arbeite im Krankenhaus. Ich bin Arzt.","question":"What is the speaker’s job?","choices":["Teacher","Doctor","Driver"],"answer":1},"writing":{"prompt":"Write three sentences about your work or studies.","model":"Ich bin Student. Ich studiere IT. Ich lerne Deutsch."},"speaking":{"prompt":"Answer: Was machen Sie beruflich? Lernen Sie Deutsch?","model":"Ich bin Student. Ja, ich lerne Deutsch."}},{"id":"a1-10","number":10,"title":"Home & rooms","group":"People & home","grammar":{"title":"wo? / in + location","en":"Use Wo wohnst du? to ask where someone lives. Ich wohne in einer Wohnung is a useful A1 answer.","ne":"Wo wohnst du? = तिमी कहाँ बस्छौ?","example":"Ich wohne in einer kleinen Wohnung.","exampleEn":"I live in a small apartment.","exampleNe":"म सानो अपार्टमेन्टमा बस्छु।","pronEnglish":"ikh VOH-nuh in AI-ner KLAI-nen VOH-noong","pronNepali":"इख वोने इन आइनर क्लाइनन वोनुङ"},"vocab":[{"de":"die Wohnung","en":"apartment","ne":"अपार्टमेन्ट"},{"de":"das Haus","en":"house","ne":"घर"},{"de":"das Zimmer","en":"room","ne":"कोठा"},{"de":"die Küche","en":"kitchen","ne":"भान्सा"},{"de":"das Bad","en":"bathroom","ne":"स्नानघर"},{"de":"das Schlafzimmer","en":"bedroom","ne":"सुत्ने कोठा"},{"de":"die Tür","en":"door","ne":"ढोका"}],"reading":{"text":"Die Wohnung hat zwei Zimmer, eine Küche und ein Bad.","question":"How many rooms are mentioned as Zimmer?","choices":["Three","Two","One"],"answer":1},"listening":{"text":"Ich wohne im zweiten Stock. Die Küche ist klein.","question":"What is small?","choices":["The balcony","The garden","The kitchen"],"answer":2},"writing":{"prompt":"Describe your home in three sentences.","model":"Ich wohne in einer Wohnung. Sie hat zwei Zimmer. Die Küche ist klein."},"speaking":{"prompt":"Answer: Wo wohnen Sie? Wie viele Zimmer haben Sie?","model":"Ich wohne in Berlin. Meine Wohnung hat zwei Zimmer."}},{"id":"a1-11","number":11,"title":"Objects & articles","group":"People & home","grammar":{"title":"der / die / das","en":"Every German noun has a grammatical gender. Learn nouns with their articles, for example der Tisch, die Lampe, das Buch.","ne":"जर्मन संज्ञालाई der, die, das सँगै याद गर्नुहोस्।","example":"Das ist ein Buch. Die Lampe ist neu.","exampleEn":"That is a book. The lamp is new.","exampleNe":"त्यो किताब हो। बत्ती नयाँ छ।","pronEnglish":"das ist ain BOOKH dee LAM-puh ist noy","pronNepali":"दास इस्ट आइन बुख दी लाम्पे इस्ट नोइ"},"vocab":[{"de":"der Tisch","en":"table","ne":"टेबल"},{"de":"die Lampe","en":"lamp","ne":"बत्ती"},{"de":"das Buch","en":"book","ne":"किताब"},{"de":"der Stuhl","en":"chair","ne":"कुर्सी"},{"de":"die Tasche","en":"bag","ne":"झोला"},{"de":"das Fenster","en":"window","ne":"झ्याल"},{"de":"das Handy","en":"mobile phone","ne":"मोबाइल"}],"reading":{"text":"Auf dem Tisch liegen ein Buch und eine Tasche.","question":"What is on the table?","choices":["A phone only","A lamp only","A book and bag"],"answer":2},"listening":{"text":"Die Lampe ist neu, aber der Tisch ist alt.","question":"Which object is new?","choices":["The lamp","The table","The window"],"answer":0},"writing":{"prompt":"Write one sentence with der, one with die and one with das.","model":"Der Tisch ist groß. Die Lampe ist neu. Das Buch ist interessant."},"speaking":{"prompt":"Point to three objects and say their articles.","model":"Das ist der Tisch. Das ist die Tasche. Das ist das Buch."}},{"id":"a1-12","number":12,"title":"Present tense: regular verbs","group":"Grammar & communication","grammar":{"title":"ich -e, du -st, er/sie -t","en":"Regular verbs often use endings -e, -st, -t, -en. For lernen: ich lerne, du lernst, er lernt, wir lernen.","ne":"क्रियामा व्यक्ति अनुसार -e, -st, -t आदि अन्त्य बदलिन्छ।","example":"Ich lerne Deutsch. Du lernst Englisch.","exampleEn":"I learn German. You learn English.","exampleNe":"म जर्मन सिक्छु। तिमी अङ्ग्रेजी सिक्छौ।","pronEnglish":"ikh LEHR-nuh DOITCH doo LEHRNST ENG-lish","pronNepali":"इख लेर्ने डोइच डू लेर्न्स्ट एङ्ग्लिश"},"vocab":[{"de":"lernen","en":"learn","ne":"सिक्नु"},{"de":"machen","en":"do / make","ne":"गर्नु"},{"de":"spielen","en":"play","ne":"खेल्नु"},{"de":"kaufen","en":"buy","ne":"किन्नु"},{"de":"fragen","en":"ask","ne":"सोध्नु"},{"de":"hören","en":"hear","ne":"सुन्नु"},{"de":"wohnen","en":"live","ne":"बस्नु"}],"reading":{"text":"Anna lernt Deutsch, aber Ben lernt Spanisch.","question":"Which language does Anna learn?","choices":["German","Spanish","French"],"answer":0},"listening":{"text":"Ich spiele Fußball. Meine Schwester spielt Tennis.","question":"What does the speaker play?","choices":["Tennis","Football","Basketball"],"answer":1},"writing":{"prompt":"Write three sentences using different verb subjects.","model":"Ich lerne Deutsch. Du spielst Tennis. Wir wohnen hier."},"speaking":{"prompt":"Say what you and a friend do each day.","model":"Ich lerne Deutsch. Mein Freund arbeitet."}},{"id":"a1-13","number":13,"title":"sein & haben","group":"Grammar & communication","grammar":{"title":"Irregular present verbs","en":"Sein: ich bin, du bist, er ist, wir sind. Haben: ich habe, du hast, er hat, wir haben.","ne":"sein र haben महत्त्वपूर्ण अनियमित क्रिया हुन्।","example":"Ich bin müde, aber ich habe Zeit.","exampleEn":"I am tired, but I have time.","exampleNe":"म थाकेको छु तर मसँग समय छ।","pronEnglish":"ikh bin MYOO-duh ah-ber ikh HAH-buh tsait","pronNepali":"इख बिन म्यूडे आबेर इख हाबे त्साइट"},"vocab":[{"de":"sein","en":"to be","ne":"हुनु"},{"de":"haben","en":"to have","ne":"हुनु / साथमा हुनु"},{"de":"bin","en":"am","ne":"छु"},{"de":"bist","en":"are (du)","ne":"छौ"},{"de":"ist","en":"is","ne":"छ"},{"de":"habe","en":"have (ich)","ne":"मसँग छ"},{"de":"hat","en":"has (er/sie)","ne":"उससँग छ"}],"reading":{"text":"Leo ist müde. Er hat heute keinen Unterricht.","question":"How does Leo feel?","choices":["Happy","Tired","Hungry"],"answer":1},"listening":{"text":"Ich habe zwei Kinder. Meine Kinder sind sechs und acht Jahre alt.","question":"How many children?","choices":["Three","One","Two"],"answer":2},"writing":{"prompt":"Write two sentences with sein and two with haben.","model":"Ich bin Student. Meine Schwester ist nett. Ich habe Zeit. Wir haben ein Auto."},"speaking":{"prompt":"Answer: Sind Sie Student? Haben Sie Geschwister?","model":"Ja, ich bin Student. Ja, ich habe eine Schwester."}},{"id":"a1-14","number":14,"title":"Questions & word order","group":"Grammar & communication","grammar":{"title":"W-questions / yes-no questions","en":"W-questions start with wo, wer, wie, was, wann, warum. Yes/no questions begin with the conjugated verb.","ne":"प्रश्नमा Wo, Wer, Wie, Was प्रयोग हुन्छ। हो/होइन प्रश्न क्रियाबाट सुरु हुन्छ।","example":"Wo wohnst du? Wohnst du in Berlin?","exampleEn":"Where do you live? Do you live in Berlin?","exampleNe":"तिमी कहाँ बस्छौ? के तिमी बर्लिनमा बस्छौ?","pronEnglish":"voh VOHNST doo VOHNST doo in behr-LEEN","pronNepali":"वो वोन्स्ट डू वोन्स्ट डू इन बेर्लिन"},"vocab":[{"de":"wer","en":"who","ne":"को"},{"de":"was","en":"what","ne":"के"},{"de":"wo","en":"where","ne":"कहाँ"},{"de":"wann","en":"when","ne":"कहिले"},{"de":"wie","en":"how","ne":"कसरी"},{"de":"warum","en":"why","ne":"किन"},{"de":"welche","en":"which","ne":"कुन"}],"reading":{"text":"Frage: Wann fährt der Bus? Antwort: Um acht Uhr.","question":"When does the bus leave?","choices":["At nine","At seven","At eight"],"answer":2},"listening":{"text":"Wo wohnen Sie? – Ich wohne in Köln.","question":"What information was requested?","choices":["Place of residence","Age","Name"],"answer":0},"writing":{"prompt":"Write three questions using wo, wie and wann.","model":"Wo wohnst du? Wie heißt du? Wann beginnt der Kurs?"},"speaking":{"prompt":"Ask a friend about their name, city and age.","model":"Wie heißt du? Wo wohnst du? Wie alt bist du?"}},{"id":"a1-15","number":15,"title":"Negation: nicht & kein","group":"Grammar & communication","grammar":{"title":"Negation in simple sentences","en":"Use kein with a noun that would take ein, and nicht to negate many verbs/adjectives. Ich habe kein Auto. Ich arbeite nicht.","ne":"ein प्रकारको संज्ञा नकार्दा kein, क्रिया नकार्दा nicht।","example":"Ich habe kein Auto und arbeite heute nicht.","exampleEn":"I do not have a car and am not working today.","exampleNe":"मसँग गाडी छैन र आज काम गर्दिनँ।","pronEnglish":"ikh HAH-buh kain OW-toh unt AR-bai-tuh HOY-tuh nikht","pronNepali":"इख हाबे काइन आउटो उन्ट आरबाइटे होइटे निख्ट"},"vocab":[{"de":"nicht","en":"not","ne":"होइन / नगर्नु"},{"de":"kein","en":"no / not a","ne":"कुनै छैन"},{"de":"keine","en":"no (feminine/plural)","ne":"छैन"},{"de":"nie","en":"never","ne":"कहिल्यै होइन"},{"de":"heute","en":"today","ne":"आज"},{"de":"leider","en":"unfortunately","ne":"दुर्भाग्यवश"},{"de":"doch","en":"yes (contradicting no)","ne":"हो नि"}],"reading":{"text":"Bitte kommen Sie heute nicht. Der Kurs fällt aus.","question":"What is cancelled?","choices":["The course","The train","The concert"],"answer":0},"listening":{"text":"Haben Sie Milch? – Nein, leider haben wir keine Milch.","question":"What is unavailable?","choices":["Bread","Milk","Tea"],"answer":1},"writing":{"prompt":"Write two negative sentences with nicht and kein.","model":"Ich trinke keinen Kaffee. Ich komme heute nicht."},"speaking":{"prompt":"Say something you do not have and do not do.","model":"Ich habe kein Fahrrad. Ich rauche nicht."}},{"id":"a1-16","number":16,"title":"Food & drinks","group":"Everyday life","grammar":{"title":"mögen / möchten","en":"Ich mag Tee means I like tea. Ich möchte Tee means I would like tea and is polite for ordering.","ne":"Ich mag = मलाई मन पर्छ; Ich möchte = मलाई चाहिन्छ (विनम्र)।","example":"Ich möchte Brot und einen Tee, bitte.","exampleEn":"I would like bread and a tea, please.","exampleNe":"मलाई रोटी र एक कप चिया दिनुहोस्।","pronEnglish":"ikh MURKH-tuh BROHT unt AI-nen teh BIT-tuh","pronNepali":"इख म्यौख्टे ब्रोट उन्ट आइनन टे बिट्टे"},"vocab":[{"de":"das Brot","en":"bread","ne":"रोटी"},{"de":"das Wasser","en":"water","ne":"पानी"},{"de":"der Tee","en":"tea","ne":"चिया"},{"de":"der Kaffee","en":"coffee","ne":"कफी"},{"de":"die Milch","en":"milk","ne":"दूध"},{"de":"der Reis","en":"rice","ne":"भात"},{"de":"der Apfel","en":"apple","ne":"स्याउ"},{"de":"das Frühstück","en":"breakfast","ne":"बिहानको खाना"}],"reading":{"text":"Im Café kostet der Tee zwei Euro und der Kaffee drei Euro.","question":"Which drink costs three euros?","choices":["Tea","Coffee","Water"],"answer":1},"listening":{"text":"Möchten Sie Wasser oder Saft? – Wasser, bitte.","question":"What is ordered?","choices":["Juice","Coffee","Water"],"answer":2},"writing":{"prompt":"Write a simple shopping list and an order.","model":"Ich brauche Brot, Milch und Äpfel. Ich möchte einen Tee, bitte."},"speaking":{"prompt":"Order food and drink politely.","model":"Ich möchte Reis und ein Wasser, bitte."}},{"id":"a1-17","number":17,"title":"At the restaurant","group":"Everyday life","grammar":{"title":"Ordering politely","en":"Use Ich hätte gern ... or Ich möchte ... for polite orders. Ask Die Rechnung, bitte to pay.","ne":"अर्डर गर्दा Ich hätte gern / Ich möchte प्रयोग हुन्छ।","example":"Ich hätte gern eine Suppe und die Rechnung, bitte.","exampleEn":"I would like a soup and the bill, please.","exampleNe":"मलाई सुप र बिल दिनुहोस्।","pronEnglish":"ikh HET-tuh gehrn AI-nuh ZOOP-uh","pronNepali":"इख हेट्टे गेर्न आइने जुपे"},"vocab":[{"de":"die Speisekarte","en":"menu","ne":"मेनु"},{"de":"die Rechnung","en":"bill","ne":"बिल"},{"de":"die Suppe","en":"soup","ne":"सुप"},{"de":"das Essen","en":"food","ne":"खाना"},{"de":"bestellen","en":"to order","ne":"अर्डर गर्नु"},{"de":"bezahlen","en":"to pay","ne":"तिर्नु"},{"de":"lecker","en":"tasty","ne":"मीठो"}],"reading":{"text":"Das Restaurant ist täglich von 12 bis 22 Uhr geöffnet.","question":"When does the restaurant close?","choices":["12:00","20:00","22:00"],"answer":2},"listening":{"text":"Ich nehme die Suppe. Und zum Trinken ein Wasser, bitte.","question":"What food is ordered?","choices":["Soup","Salad","Bread"],"answer":0},"writing":{"prompt":"Write a short restaurant dialogue with an order.","model":"Guten Abend. Ich möchte eine Suppe, bitte. Danke. Die Rechnung, bitte."},"speaking":{"prompt":"Role-play: order food and ask for the bill.","model":"Ich hätte gern eine Suppe. Die Rechnung, bitte."}},{"id":"a1-18","number":18,"title":"Shopping & prices","group":"Everyday life","grammar":{"title":"Accusative: einen / eine / ein","en":"A masculine direct object changes ein → einen: Ich kaufe einen Apfel. Feminine eine and neuter ein stay unchanged.","ne":"कर्ममा पुरुषलिङ्ग ein → einen हुन सक्छ।","example":"Ich kaufe einen Apfel und eine Banane.","exampleEn":"I buy an apple and a banana.","exampleNe":"म स्याउ र केरा किन्छु।","pronEnglish":"ikh KOW-fuh AI-nen AP-fel unt AI-nuh bah-NAH-nuh","pronNepali":"इख काउफे आइनन आप्फल उन्ट आइने बनाने"},"vocab":[{"de":"kaufen","en":"buy","ne":"किन्नु"},{"de":"kosten","en":"cost","ne":"मूल्य पर्नु"},{"de":"billig","en":"cheap","ne":"सस्तो"},{"de":"teuer","en":"expensive","ne":"महँगो"},{"de":"der Preis","en":"price","ne":"मूल्य"},{"de":"das Geld","en":"money","ne":"पैसा"},{"de":"der Laden","en":"shop","ne":"पसल"},{"de":"die Kasse","en":"checkout","ne":"काउन्टर"}],"reading":{"text":"Der Pullover kostet 25 Euro. Heute gibt es fünf Euro Rabatt.","question":"What is the discount?","choices":["5 euros","25 euros","10 euros"],"answer":0},"listening":{"text":"Entschuldigung, was kostet das Brot? – Zwei Euro fünfzig.","question":"How much is the bread?","choices":["€5.20","€2.50","€3.00"],"answer":1},"writing":{"prompt":"Write a question about a price and an answer.","model":"Was kostet der Apfel? Er kostet einen Euro."},"speaking":{"prompt":"Ask for two items and their prices.","model":"Ich möchte einen Apfel und eine Banane. Was kostet das?"}},{"id":"a1-19","number":19,"title":"Clothes, colors & sizes","group":"Everyday life","grammar":{"title":"Adjectives for basic description","en":"Describe objects with simple adjectives: Die Jacke ist blau. For clothing size ask Welche Größe haben Sie?","ne":"रङ र आकारले सामानको वर्णन गर्न सकिन्छ।","example":"Die rote Jacke ist zu klein.","exampleEn":"The red jacket is too small.","exampleNe":"रातो ज्याकेट धेरै सानो छ।","pronEnglish":"dee ROH-tuh YAK-uh ist tsoo klain","pronNepali":"दी रोटे याके इस्ट त्सू क्लाइन"},"vocab":[{"de":"die Jacke","en":"jacket","ne":"ज्याकेट"},{"de":"die Hose","en":"trousers","ne":"पाइन्ट"},{"de":"das Hemd","en":"shirt","ne":"सर्ट"},{"de":"die Schuhe","en":"shoes","ne":"जुत्ता"},{"de":"rot","en":"red","ne":"रातो"},{"de":"blau","en":"blue","ne":"निलो"},{"de":"schwarz","en":"black","ne":"कालो"},{"de":"die Größe","en":"size","ne":"साइज"}],"reading":{"text":"Heute sind alle blauen Jacken 20 Prozent günstiger.","question":"Which clothing is discounted?","choices":["Black shoes","Blue jackets","Red trousers"],"answer":1},"listening":{"text":"Ich brauche Schuhe in Größe 42. Haben Sie schwarze Schuhe?","question":"What color is requested?","choices":["Blue","Red","Black"],"answer":2},"writing":{"prompt":"Write a description of clothing you want to buy.","model":"Ich möchte eine schwarze Jacke in Größe M."},"speaking":{"prompt":"Ask for a shirt in a size and color.","model":"Haben Sie ein blaues Hemd in Größe M?"}},{"id":"a1-20","number":20,"title":"Daily routines","group":"Everyday life","grammar":{"title":"Time adverbs and verb-second","en":"In statements the conjugated verb is usually in position 2: Am Morgen trinke ich Kaffee.","ne":"सामान्य वाक्यमा रूप बदलिएको क्रिया दोस्रो स्थानमा हुन्छ।","example":"Um sieben Uhr stehe ich auf.","exampleEn":"I get up at seven o’clock.","exampleNe":"म सात बजे उठ्छु।","pronEnglish":"oom ZEE-ben oor SHTEH-uh ikh owf","pronNepali":"उम जीबन उर श्टेए इख आउफ"},"vocab":[{"de":"aufstehen","en":"get up","ne":"उठ्नु"},{"de":"duschen","en":"take a shower","ne":"नुहाउनु"},{"de":"frühstücken","en":"eat breakfast","ne":"बिहानको खाना खानु"},{"de":"arbeiten","en":"work","ne":"काम गर्नु"},{"de":"schlafen","en":"sleep","ne":"सुत्नु"},{"de":"am Morgen","en":"in the morning","ne":"बिहान"},{"de":"am Abend","en":"in the evening","ne":"साँझ"}],"reading":{"text":"Lisa arbeitet von acht bis sechzehn Uhr. Danach geht sie nach Hause.","question":"When does Lisa finish work?","choices":["08:00","18:00","16:00"],"answer":2},"listening":{"text":"Ich stehe um sechs Uhr auf. Um sieben frühstücke ich.","question":"When does the speaker get up?","choices":["06:00","07:00","08:00"],"answer":0},"writing":{"prompt":"Write your daily routine with four time expressions.","model":"Um sieben stehe ich auf. Um acht frühstücke ich. Um neun lerne ich. Um elf schlafe ich."},"speaking":{"prompt":"Describe your morning in three sentences.","model":"Ich stehe um sieben Uhr auf. Dann dusche ich. Danach frühstücke ich."}},{"id":"a1-21","number":21,"title":"Separable verbs","group":"Everyday life","grammar":{"title":"Verb prefix moves to the end","en":"With aufstehen the prefix auf moves to sentence end: Ich stehe früh auf. In an infinitive it stays attached.","ne":"aufstehen जस्ता क्रियाको उपसर्ग वाक्यको अन्त्यमा जान्छ।","example":"Ich rufe dich heute Abend an.","exampleEn":"I will call you this evening.","exampleNe":"म आज साँझ तिमीलाई फोन गर्छु।","pronEnglish":"ikh ROO-fuh dikh HOY-tuh AH-bent an","pronNepali":"इख रुफे दिख होइटे आबेन्ट आन"},"vocab":[{"de":"anrufen","en":"to call","ne":"फोन गर्नु"},{"de":"aufstehen","en":"get up","ne":"उठ्नु"},{"de":"einkaufen","en":"shop","ne":"किनमेल गर्नु"},{"de":"fernsehen","en":"watch television","ne":"टिभी हेर्नु"},{"de":"mitkommen","en":"come along","ne":"सँगै आउनु"},{"de":"an","en":"on (prefix)","ne":"क्रियाको उपसर्ग"},{"de":"auf","en":"up (prefix)","ne":"क्रियाको उपसर्ग"}],"reading":{"text":"Die Mutter ruft ihren Sohn um acht Uhr an.","question":"When does the mother call?","choices":["08:00","18:00","07:00"],"answer":0},"listening":{"text":"Ich kaufe am Samstag ein. Am Sonntag bleibe ich zu Hause.","question":"When does the speaker shop?","choices":["Sunday","Saturday","Monday"],"answer":1},"writing":{"prompt":"Write two sentences with separable verbs.","model":"Ich stehe um sieben Uhr auf. Ich rufe meine Mutter an."},"speaking":{"prompt":"Ask a friend to come and say when you shop.","model":"Kommst du mit? Ich kaufe morgen ein."}},{"id":"a1-22","number":22,"title":"Appointments & invitations","group":"Situations","grammar":{"title":"können / möchten / imperative requests","en":"Use Können Sie ...? for polite requests and Hast du Zeit? for an informal invitation.","ne":"विनम्र अनुरोधका लागि Können Sie ...? प्रयोग गर्नुहोस्।","example":"Hast du am Samstag Zeit?","exampleEn":"Do you have time on Saturday?","exampleNe":"तिमीसँग शनिबार समय छ?","pronEnglish":"hast doo am ZAHMS-tahk tsait","pronNepali":"हास्ट डू आम जाम्सटाक त्साइट"},"vocab":[{"de":"der Termin","en":"appointment","ne":"भेटघाट"},{"de":"die Einladung","en":"invitation","ne":"निमन्त्रणा"},{"de":"Zeit haben","en":"have time","ne":"समय हुनु"},{"de":"kommen","en":"come","ne":"आउनु"},{"de":"treffen","en":"meet","ne":"भेट्नु"},{"de":"absagen","en":"cancel","ne":"रद्द गर्नु"},{"de":"verschieben","en":"postpone","ne":"सार्नु"}],"reading":{"text":"Liebe Sara, wir treffen uns am Freitag um 18 Uhr im Park.","question":"Where is the meeting?","choices":["At the station","In the park","At a café"],"answer":1},"listening":{"text":"Hallo Tom. Kannst du am Sonntag um zehn Uhr kommen?","question":"What day is proposed?","choices":["Saturday","Monday","Sunday"],"answer":2},"writing":{"prompt":"Write a 25–35 word invitation to a friend.","model":"Hallo Anna, ich habe am Samstag Geburtstag. Komm bitte um 18 Uhr zu mir. Wir essen zusammen. Kannst du kommen? Liebe Grüße, Ravi."},"speaking":{"prompt":"Invite a friend and ask for a reply.","model":"Hast du am Sonntag Zeit? Komm bitte um fünf Uhr. Geht das?"}},{"id":"a1-23","number":23,"title":"Directions & transport","group":"Situations","grammar":{"title":"wohin? / nach / zu","en":"Use nach with many cities/countries (nach Berlin), zu for a person or destination (zum Arzt).","ne":"सहरका लागि nach Berlin, व्यक्तिका लागि zum Arzt भन्न सकिन्छ।","example":"Wie komme ich zum Bahnhof?","exampleEn":"How do I get to the railway station?","exampleNe":"म रेल स्टेसन कसरी पुग्छु?","pronEnglish":"vee KOM-uh ikh tsoom BAHN-hohf","pronNepali":"वी कोमे इख त्सुम बान्होफ"},"vocab":[{"de":"der Bahnhof","en":"railway station","ne":"रेल स्टेसन"},{"de":"der Bus","en":"bus","ne":"बस"},{"de":"der Zug","en":"train","ne":"रेल"},{"de":"das Ticket","en":"ticket","ne":"टिकट"},{"de":"links","en":"left","ne":"बायाँ"},{"de":"rechts","en":"right","ne":"दायाँ"},{"de":"geradeaus","en":"straight ahead","ne":"सिधा"},{"de":"die Haltestelle","en":"bus stop","ne":"बस स्टप"}],"reading":{"text":"Der Bus 12 fährt zum Bahnhof. Er hält vor der Schule.","question":"Which bus goes to the station?","choices":["21","2","12"],"answer":2},"listening":{"text":"Gehen Sie geradeaus und dann nach links. Dort ist die Post.","question":"Which way after going straight?","choices":["Left","Right","Back"],"answer":0},"writing":{"prompt":"Write short directions from your home to a nearby stop.","model":"Gehen Sie geradeaus. Dann gehen Sie rechts. Die Haltestelle ist links."},"speaking":{"prompt":"Ask directions politely and repeat them.","model":"Entschuldigung, wo ist der Bahnhof? Geradeaus und dann links? Danke!"}},{"id":"a1-24","number":24,"title":"Places & local services","group":"Situations","grammar":{"title":"es gibt + accusative","en":"Es gibt means there is/there are. Es gibt hier einen Supermarkt. Ask Wo gibt es ...?","ne":"Es gibt = यहाँ ... छ / छन्।","example":"In meiner Stadt gibt es eine Apotheke.","exampleEn":"In my town there is a pharmacy.","exampleNe":"मेरो सहरमा एउटा औषधि पसल छ।","pronEnglish":"in MAI-ner shtat gipt ess AI-nuh ah-poh-TEH-kuh","pronNepali":"इन माइनर श्टाट गिब्ट एस आइने आपोटेके"},"vocab":[{"de":"die Apotheke","en":"pharmacy","ne":"औषधि पसल"},{"de":"die Post","en":"post office","ne":"हुलाक"},{"de":"die Bank","en":"bank","ne":"बैंक"},{"de":"der Supermarkt","en":"supermarket","ne":"सुपरमार्केट"},{"de":"das Rathaus","en":"town hall","ne":"नगरपालिका कार्यालय"},{"de":"die Schule","en":"school","ne":"विद्यालय"},{"de":"das Krankenhaus","en":"hospital","ne":"अस्पताल"}],"reading":{"text":"Die Apotheke ist neben der Bank. Sie öffnet um 9 Uhr.","question":"What is beside the bank?","choices":["Pharmacy","School","Hospital"],"answer":0},"listening":{"text":"Gibt es hier einen Supermarkt? – Ja, neben der Post.","question":"Where is the supermarket?","choices":["By the bank","By the post office","By the park"],"answer":1},"writing":{"prompt":"Write which services are near your home.","model":"Bei mir gibt es einen Supermarkt, eine Bank und eine Apotheke."},"speaking":{"prompt":"Ask where to find a pharmacy.","model":"Entschuldigung, wo gibt es hier eine Apotheke?"}},{"id":"a1-25","number":25,"title":"Health & at the doctor","group":"Situations","grammar":{"title":"mir tut ... weh","en":"Use Mir tut der Kopf weh (my head hurts) or Ich habe Kopfschmerzen. Ask for an appointment politely.","ne":"दुखाइ बताउँदा mir tut ... weh प्रयोग हुन्छ।","example":"Mir tut der Kopf weh. Ich brauche einen Termin.","exampleEn":"My head hurts. I need an appointment.","exampleNe":"मेरो टाउको दुख्छ। मलाई अपोइन्टमेन्ट चाहिन्छ।","pronEnglish":"meer toot dehr KOPF veh","pronNepali":"मीर टूट देर कोप्फ वे"},"vocab":[{"de":"der Arzt","en":"doctor (male)","ne":"डाक्टर"},{"de":"die Ärztin","en":"doctor (female)","ne":"महिला चिकित्सक"},{"de":"krank","en":"ill","ne":"बिरामी"},{"de":"der Kopf","en":"head","ne":"टाउको"},{"de":"der Bauch","en":"stomach","ne":"पेट"},{"de":"der Schmerz","en":"pain","ne":"दुखाइ"},{"de":"das Rezept","en":"prescription","ne":"औषधि पर्चा"}],"reading":{"text":"Die Praxis ist heute bis 16 Uhr geöffnet. Morgen ist sie geschlossen.","question":"Until when is the office open?","choices":["18:00","16:00","12:00"],"answer":1},"listening":{"text":"Ich habe Fieber. Können Sie mir bitte heute einen Termin geben?","question":"What does the caller want?","choices":["A hotel booking","A ticket","A doctor appointment"],"answer":2},"writing":{"prompt":"Write a short message requesting a doctor’s appointment.","model":"Guten Tag, ich bin krank und habe Fieber. Haben Sie heute einen Termin für mich? Vielen Dank."},"speaking":{"prompt":"Explain one symptom and ask for help.","model":"Guten Tag. Ich habe Kopfschmerzen. Ich brauche einen Termin."}},{"id":"a1-26","number":26,"title":"Weather & seasons","group":"Situations","grammar":{"title":"es ist + adjective","en":"Use Es ist kalt/warm/sonnig, or Es regnet. Weather sentences often start with es.","ne":"मौसममा Es ist kalt / Es regnet प्रयोग हुन्छ।","example":"Heute ist es kalt und es regnet.","exampleEn":"Today it is cold and raining.","exampleNe":"आज चिसो छ र पानी परिरहेको छ।","pronEnglish":"HOY-tuh ist ess kalt unt ess REHG-net","pronNepali":"होइटे इस्ट एस काल्ट उन्ट एस रेग्नेट"},"vocab":[{"de":"der Sommer","en":"summer","ne":"गर्मी"},{"de":"der Winter","en":"winter","ne":"जाडो"},{"de":"der Frühling","en":"spring","ne":"वसन्त"},{"de":"der Herbst","en":"autumn","ne":"शरद"},{"de":"die Sonne","en":"sun","ne":"घाम"},{"de":"der Regen","en":"rain","ne":"वर्षा"},{"de":"kalt","en":"cold","ne":"चिसो"},{"de":"warm","en":"warm","ne":"न्यानो"}],"reading":{"text":"Am Samstag ist es sonnig. Am Sonntag regnet es stark.","question":"What is Saturday’s weather?","choices":["Rainy","Snowy","Sunny"],"answer":2},"listening":{"text":"Morgen sind es zehn Grad und es regnet.","question":"How is the weather tomorrow?","choices":["Rainy","Sunny","Hot"],"answer":0},"writing":{"prompt":"Write a short weather report for today and tomorrow.","model":"Heute ist es warm und sonnig. Morgen regnet es."},"speaking":{"prompt":"Describe the weather and your favorite season.","model":"Heute ist es kalt. Ich mag den Sommer."}},{"id":"a1-27","number":27,"title":"Free time & hobbies","group":"Situations","grammar":{"title":"gern / lieber / am liebsten","en":"Use gern after a verb for liking an activity. Lieber means prefer. Am liebsten means like most.","ne":"gern = गर्न मन पर्छ; lieber = बढी मन पर्छ।","example":"Ich lese gern und spiele manchmal Fußball.","exampleEn":"I like reading and sometimes play football.","exampleNe":"मलाई पढ्न मन पर्छ र कहिलेकाहीँ फुटबल खेल्छु।","pronEnglish":"ikh LEH-zuh gehrn unt SHPEE-luh MANCH-mahl FOOSS-ball","pronNepali":"इख लेजे गेर्न उन्ट श्पीले मान्खमाल फुसबाल"},"vocab":[{"de":"das Hobby","en":"hobby","ne":"रुचि"},{"de":"lesen","en":"read","ne":"पढ्नु"},{"de":"schwimmen","en":"swim","ne":"पौडिनु"},{"de":"tanzen","en":"dance","ne":"नाच्नु"},{"de":"die Musik","en":"music","ne":"सङ्गीत"},{"de":"das Kino","en":"cinema","ne":"सिनेमा"},{"de":"das Wochenende","en":"weekend","ne":"सप्ताहन्त"}],"reading":{"text":"Max geht samstags ins Kino. Sonntags liest er zu Hause.","question":"What does Max do on Sunday?","choices":["Read at home","Go to cinema","Go swimming"],"answer":0},"listening":{"text":"Ich spiele gern Tennis, aber meine Freundin schwimmt lieber.","question":"What does the friend prefer?","choices":["Tennis","Swimming","Reading"],"answer":1},"writing":{"prompt":"Write three short sentences about your hobbies.","model":"Ich lese gern Bücher. Ich höre Musik. Am Wochenende spiele ich Fußball."},"speaking":{"prompt":"Ask a friend about hobbies and share yours.","model":"Was machst du gern? Ich höre gern Musik."}},{"id":"a1-28","number":28,"title":"Modal verbs & requests","group":"Situations","grammar":{"title":"können / müssen / wollen / dürfen","en":"After a modal verb, another verb stays in the infinitive at the end: Ich muss heute arbeiten.","ne":"Modal क्रियापछि अर्को क्रिया वाक्यको अन्त्यमा मूल रूपमा आउँछ।","example":"Ich kann heute kommen, aber ich muss früh gehen.","exampleEn":"I can come today, but I must leave early.","exampleNe":"म आज आउन सक्छु तर चाँडै जानुपर्छ।","pronEnglish":"ikh kan HOY-tuh KOM-en ah-ber ikh moos froo GEH-en","pronNepali":"इख कान होइटे कोमेन आबेर इख मुस फ्रु गेएन"},"vocab":[{"de":"können","en":"can","ne":"सक्नु"},{"de":"müssen","en":"must","ne":"गर्नुपर्नु"},{"de":"wollen","en":"want","ne":"चाहनु"},{"de":"dürfen","en":"be allowed","ne":"अनुमति पाउनु"},{"de":"sollen","en":"should","ne":"गर्नुपर्ने"},{"de":"helfen","en":"help","ne":"मद्दत गर्नु"},{"de":"bitten","en":"request","ne":"अनुरोध गर्नु"}],"reading":{"text":"Bitte seien Sie pünktlich. Sie müssen um acht Uhr da sein.","question":"What time must the person arrive?","choices":["09:00","08:00","10:00"],"answer":1},"listening":{"text":"Können Sie bitte das Fenster öffnen? – Ja, natürlich.","question":"What is requested?","choices":["Close the door","Call a taxi","Open the window"],"answer":2},"writing":{"prompt":"Write three requests with modal verbs.","model":"Können Sie mir helfen? Ich muss heute arbeiten. Darf ich hier sitzen?"},"speaking":{"prompt":"Make a polite request and ask permission.","model":"Können Sie mir bitte helfen? Darf ich hier sitzen?"}},{"id":"a1-29","number":29,"title":"Hotel & travel","group":"Situations","grammar":{"title":"ich möchte + booking","en":"Request a room with Ich möchte ein Zimmer buchen. Provide number of nights and a date.","ne":"कोठा बुक गर्दा Ich möchte ein Zimmer buchen भन्नुहोस्।","example":"Ich möchte ein Zimmer für zwei Nächte buchen.","exampleEn":"I would like to book a room for two nights.","exampleNe":"म दुई रातका लागि कोठा बुक गर्न चाहन्छु।","pronEnglish":"ikh MURKH-tuh ain TSIM-er fyoor tsvai NEKH-tuh BOO-khen","pronNepali":"इख म्यौख्टे आइन त्सिमर फ्युर त्स्वाइ नेख्टे बुखन"},"vocab":[{"de":"das Hotel","en":"hotel","ne":"होटल"},{"de":"das Zimmer","en":"room","ne":"कोठा"},{"de":"die Nacht","en":"night","ne":"रात"},{"de":"buchen","en":"book","ne":"बुक गर्नु"},{"de":"der Reisepass","en":"passport","ne":"राहदानी"},{"de":"die Reservierung","en":"reservation","ne":"बुकिङ"},{"de":"die Reise","en":"trip","ne":"यात्रा"}],"reading":{"text":"Hotel Alba: Einzelzimmer ab 60 Euro pro Nacht. Frühstück inklusive.","question":"What is included?","choices":["Dinner","Transport","Breakfast"],"answer":2},"listening":{"text":"Guten Tag, ich habe ein Zimmer für zwei Nächte reserviert.","question":"How many nights?","choices":["Two","Three","One"],"answer":0},"writing":{"prompt":"Write a short hotel booking request.","model":"Guten Tag, ich möchte ein Zimmer für zwei Nächte buchen. Haben Sie am Montag ein Zimmer frei? Vielen Dank."},"speaking":{"prompt":"Book a room and state how many nights.","model":"Ich möchte ein Zimmer für zwei Nächte, bitte."}},{"id":"a1-30","number":30,"title":"Past events: first steps","group":"Situations","grammar":{"title":"Perfekt: haben / sein + participle","en":"Recognize common Perfekt forms in simple conversation: Ich habe gelernt. Ich bin nach Hause gegangen. Many movement verbs use sein.","ne":"साधारण बितेका घटना: ich habe gelernt, ich bin gegangen।","example":"Gestern habe ich Deutsch gelernt.","exampleEn":"Yesterday I studied German.","exampleNe":"हिजो मैले जर्मन पढेँ।","pronEnglish":"GEHS-tern HAH-buh ikh DOITCH geh-LEHRNT","pronNepali":"गेस्टर्न हाबे इख डोइच गेलेर्न्ट"},"vocab":[{"de":"gestern","en":"yesterday","ne":"हिजो"},{"de":"letzte Woche","en":"last week","ne":"गत हप्ता"},{"de":"gemacht","en":"done / made","ne":"गरेको"},{"de":"gelernt","en":"learned","ne":"सिकेको"},{"de":"gegessen","en":"eaten","ne":"खाएको"},{"de":"gegangen","en":"gone","ne":"गएको"},{"de":"gefahren","en":"travelled / driven","ne":"यात्रा गरेको"}],"reading":{"text":"Gestern hat Tim gekocht. Am Abend hat er Deutsch gelernt.","question":"What did Tim do in the evening?","choices":["Studied German","Cooked","Went swimming"],"answer":0},"listening":{"text":"Ich bin gestern nach Hamburg gefahren und habe dort Freunde besucht.","question":"Where did the speaker travel?","choices":["Berlin","Hamburg","Bonn"],"answer":1},"writing":{"prompt":"Write two simple sentences about yesterday.","model":"Gestern habe ich Deutsch gelernt. Danach habe ich gekocht."},"speaking":{"prompt":"Say what you did yesterday.","model":"Gestern habe ich gearbeitet und Musik gehört."}},{"id":"a1-31","number":31,"title":"Short messages & email","group":"Exam preparation","grammar":{"title":"Hallo / Liebe Grüße / Sie","en":"An informal message uses Hallo ... and Liebe Grüße. A formal message often begins Guten Tag or Sehr geehrte ... and ends Mit freundlichen Grüßen.","ne":"अनौपचारिक पत्रमा Hallo / Liebe Grüße; औपचारिकमा Guten Tag प्रयोग गर्नुहोस्।","example":"Hallo Anna, ich kann heute nicht kommen.","exampleEn":"Hi Anna, I cannot come today.","exampleNe":"हेलो अन्ना, म आज आउन सक्दिनँ।","pronEnglish":"HAH-loh AN-ah ikh kan HOY-tuh nikht KOM-en","pronNepali":"हालो आना इख कान होइटे निख्ट कोमेन"},"vocab":[{"de":"die Nachricht","en":"message","ne":"सन्देश"},{"de":"die E-Mail","en":"email","ne":"इमेल"},{"de":"schreiben","en":"write","ne":"लेख्नु"},{"de":"senden","en":"send","ne":"पठाउनु"},{"de":"die Adresse","en":"address","ne":"ठेगाना"},{"de":"Liebe Grüße","en":"best wishes","ne":"शुभकामना सहित"},{"de":"vielen Dank","en":"many thanks","ne":"धेरै धन्यवाद"}],"reading":{"text":"Hallo Sara, der Deutschkurs fällt morgen aus. Wir sehen uns am Montag. Liebe Grüße, Mia.","question":"When is the next meeting?","choices":["Tomorrow","Monday","Sunday"],"answer":1},"listening":{"text":"Hallo Ben, ich bin krank und komme heute nicht zur Arbeit.","question":"Why is the speaker absent?","choices":["Vacation","Travel","Illness"],"answer":2},"writing":{"prompt":"Write a 30-word message canceling an appointment and suggesting a new time.","model":"Hallo Ali, leider kann ich morgen nicht kommen. Ich bin krank. Können wir uns am Freitag um 15 Uhr treffen? Bitte schreib mir. Liebe Grüße, Mira."},"speaking":{"prompt":"Tell a friend that you cannot come and suggest another day.","model":"Leider kann ich heute nicht kommen. Geht es morgen?"}},{"id":"a1-32","number":32,"title":"Forms & personal data","group":"Exam preparation","grammar":{"title":"Form fields and basic facts","en":"Be able to fill in Vorname, Nachname, Geburtsdatum, Anschrift, Land and Telefonnummer. Do not share sensitive real information for practice.","ne":"फारममा नाम, जन्ममिति, ठेगाना, फोन लेख्ने अभ्यास गर्नुहोस्।","example":"Mein Vorname ist Maya, mein Nachname ist Rai.","exampleEn":"My first name is Maya, my surname is Rai.","exampleNe":"मेरो पहिलो नाम माया र थर राई हो।","pronEnglish":"main FOR-nah-muh ist MAH-yah","pronNepali":"माइन फोरनामे इस्ट माया"},"vocab":[{"de":"der Vorname","en":"first name","ne":"नाम"},{"de":"der Nachname","en":"surname","ne":"थर"},{"de":"das Geburtsdatum","en":"date of birth","ne":"जन्ममिति"},{"de":"die Anschrift","en":"address","ne":"ठेगाना"},{"de":"die Postleitzahl","en":"postal code","ne":"हुलाक कोड"},{"de":"die Unterschrift","en":"signature","ne":"हस्ताक्षर"},{"de":"ledig","en":"single (marital status)","ne":"अविवाहित"}],"reading":{"text":"Anmeldeformular: Vorname Eva, Nachname Sommer, Wohnort Bonn.","question":"Where does Eva live?","choices":["Berlin","Hamburg","Bonn"],"answer":2},"listening":{"text":"Bitte schreiben Sie Ihren Namen und Ihre Telefonnummer auf das Formular.","question":"What must be written?","choices":["Name and telephone","Age and hobby","Price and city"],"answer":0},"writing":{"prompt":"Complete a fictional form with name, city, birth date and phone number.","model":"Vorname: Mina; Nachname: Shah; Wohnort: Bonn; Geburtsdatum: 03.05.2000; Telefon: 01234."},"speaking":{"prompt":"Practice answering a request for your name, city and age (use fictional details).","model":"Ich heiße Mia. Ich wohne in Berlin. Ich bin 24 Jahre alt."}},{"id":"a1-33","number":33,"title":"Reading signs & notices","group":"Exam preparation","grammar":{"title":"Read practical notices","en":"Scan short signs for place, dates, times, price and prohibitions. Look for words such as geschlossen, geöffnet, Eintritt frei.","ne":"सूचनामा समय, स्थान, मिति र निषेध पहिचान गर्नुहोस्।","example":"Die Bibliothek ist heute geschlossen.","exampleEn":"The library is closed today.","exampleNe":"पुस्तकालय आज बन्द छ।","pronEnglish":"dee bee-blee-oh-TEHK ist HOY-tuh geh-SHLOSS-en","pronNepali":"दी बिब्लिओटेक इस्ट होइटे गेश्लोसन"},"vocab":[{"de":"geöffnet","en":"open","ne":"खुला"},{"de":"geschlossen","en":"closed","ne":"बन्द"},{"de":"der Eingang","en":"entrance","ne":"प्रवेशद्वार"},{"de":"der Ausgang","en":"exit","ne":"निकास"},{"de":"verboten","en":"forbidden","ne":"निषेध"},{"de":"der Eintritt","en":"admission","ne":"प्रवेश"},{"de":"frei","en":"free / available","ne":"निःशुल्क / खाली"}],"reading":{"text":"Museum: Montag geschlossen. Dienstag bis Sonntag: 10–17 Uhr. Eintritt: 5 Euro.","question":"When is the museum closed?","choices":["Monday","Tuesday","Sunday"],"answer":0},"listening":{"text":"Achtung! Der Zug nach Köln fährt heute von Gleis fünf.","question":"Which platform?","choices":["Three","Five","Six"],"answer":1},"writing":{"prompt":"Write a brief sign with opening hours and an entry price.","model":"Geöffnet: Montag bis Freitag, 9–17 Uhr. Eintritt frei."},"speaking":{"prompt":"Explain a sign: Heute geschlossen.","model":"Das Geschäft ist heute geschlossen."}},{"id":"a1-34","number":34,"title":"Listening: everyday messages","group":"Exam preparation","grammar":{"title":"Listen for details, not every word","en":"Listen twice if needed. Focus on one detail: time, price, name, place, or reason. Device speech is practice, not authentic Goethe audio.","ne":"सबै शब्द बुझ्नुपर्दैन। समय, मिति, स्थान र मूल्य जस्ता मुख्य जानकारी सुन्नुहोस्।","example":"Der Termin ist nicht um acht, sondern um neun.","exampleEn":"The appointment is not at eight but at nine.","exampleNe":"अपोइन्टमेन्ट आठ होइन, नौ बजे हो।","pronEnglish":"dehr tehr-MEEN ist nikht oom akht ZON-dern oom noin","pronNepali":"देर टेर्मिन इस्ट निख्ट उम आख्ट जोन्डर्न उम नोइन"},"vocab":[{"de":"die Durchsage","en":"announcement","ne":"घोषणा"},{"de":"die Nachricht","en":"message","ne":"सन्देश"},{"de":"hören","en":"listen / hear","ne":"सुन्नु"},{"de":"wiederholen","en":"repeat","ne":"दोहोर्‍याउनु"},{"de":"langsam","en":"slowly","ne":"बिस्तारै"},{"de":"noch einmal","en":"once more","ne":"फेरि एक पटक"},{"de":"die Information","en":"information","ne":"जानकारी"}],"reading":{"text":"Bitte beachten Sie: Das Büro öffnet heute erst um zehn Uhr.","question":"When does the office open?","choices":["09:00","10:00","11:00"],"answer":1},"listening":{"text":"Achtung, eine Durchsage: Der Zug nach Bonn fährt heute zwanzig Minuten später.","question":"What is different?","choices":["The train is cancelled","The train is early","The train is late"],"answer":2},"writing":{"prompt":"Write one sentence reporting an appointment change.","model":"Der Termin ist heute um neun Uhr, nicht um acht Uhr."},"speaking":{"prompt":"Ask someone politely to repeat an announcement.","model":"Entschuldigung, können Sie das bitte wiederholen?"}},{"id":"a1-35","number":35,"title":"Speaking: introduction & requests","group":"Exam preparation","grammar":{"title":"A1 speaking task routines","en":"Practice three speaking types: introduce yourself, ask/answer simple questions, make/respond to a polite request. Partner practice is important.","ne":"परिचय दिनुहोस्, सरल प्रश्न सोध्नुहोस्, अनि विनम्र अनुरोध गर्नुहोस्।","example":"Können Sie mir bitte das Buch geben?","exampleEn":"Could you please give me the book?","exampleNe":"के तपाईं मलाई किताब दिन सक्नुहुन्छ?","pronEnglish":"KURN-en zee meer BIT-tuh das BOOKH GEH-ben","pronNepali":"क्योनन जी मीर बिट्टे दास बुख गेवन"},"vocab":[{"de":"vorstellen","en":"introduce","ne":"परिचय दिनु"},{"de":"fragen","en":"ask","ne":"सोध्नु"},{"de":"antworten","en":"answer","ne":"जवाफ दिनु"},{"de":"bitten","en":"request","ne":"अनुरोध गर्नु"},{"de":"geben","en":"give","ne":"दिनु"},{"de":"wiederholen","en":"repeat","ne":"दोहोर्‍याउनु"},{"de":"Entschuldigung","en":"excuse me / sorry","ne":"माफ गर्नुहोस्"}],"reading":{"text":"Guten Tag. Ich heiße Sara, komme aus Nepal und wohne in Bonn.","question":"Where does Sara live?","choices":["Nepal","Köln","Bonn"],"answer":2},"listening":{"text":"Können Sie mir bitte das Handy geben? – Ja, gern.","question":"What is requested?","choices":["The phone","The bag","The book"],"answer":0},"writing":{"prompt":"Write your self-introduction with name, country, city, language and hobby.","model":"Ich heiße Sara. Ich komme aus Nepal. Ich wohne in Bonn. Ich spreche Nepali und Deutsch. Ich lese gern."},"speaking":{"prompt":"Introduce yourself, ask a question, and make a polite request.","model":"Ich heiße Samir. Wo wohnen Sie? Können Sie mir bitte helfen?"}},{"id":"a1-36","number":36,"title":"A1 review & next steps","group":"Exam preparation","grammar":{"title":"Check all four skills","en":"A1 preparation involves understanding short everyday German, reading simple notices, completing forms and messages, and exchanging basic information.","ne":"A1 तयारीमा सुन्ने, पढ्ने, लेख्ने र बोल्ने चारै सीप चाहिन्छ।","example":"Ich kann mich vorstellen und einfache Fragen stellen.","exampleEn":"I can introduce myself and ask simple questions.","exampleNe":"म आफ्नो परिचय दिन र सरल प्रश्न सोध्न सक्छु।","pronEnglish":"ikh kan mikh FOR-shtel-en unt AI-nfah-khuh FRAH-gen SHTEL-en","pronNepali":"इख कान मिख फोर्श्टेलन उन्ट आइनफाखे फ्रागन श्टेलन"},"vocab":[{"de":"die Prüfung","en":"exam","ne":"परीक्षा"},{"de":"das Hören","en":"listening","ne":"श्रवण"},{"de":"das Lesen","en":"reading","ne":"पठन"},{"de":"das Schreiben","en":"writing","ne":"लेखन"},{"de":"das Sprechen","en":"speaking","ne":"बोलाइ"},{"de":"üben","en":"practice","ne":"अभ्यास गर्नु"},{"de":"verstehen","en":"understand","ne":"बुझ्नु"}],"reading":{"text":"Prüfung am Dienstag: Hören 9:00 Uhr, Lesen 9:30 Uhr. Bitte um 8:45 Uhr kommen.","question":"When must candidates arrive?","choices":["08:45","09:00","09:30"],"answer":0},"listening":{"text":"Bitte bringen Sie Ihren Ausweis mit. Die Prüfung beginnt um neun Uhr.","question":"What must participants bring?","choices":["A book","ID","A ticket"],"answer":1},"writing":{"prompt":"Write a short email explaining you will be late and asking for information.","model":"Guten Tag, leider komme ich zehn Minuten später. Wann beginnt der Kurs? Vielen Dank. Mit freundlichen Grüßen, Mina."},"speaking":{"prompt":"Practice a full A1 self-introduction and two everyday questions.","model":"Guten Tag. Ich heiße Mina. Ich komme aus Nepal. Ich wohne in Bonn. Ich lerne Deutsch. Wie heißen Sie? Was machen Sie gern?"}}],"exam":{"disclaimer":"Independent original practice; not a Goethe exam and not an official score. For a realistic simulation, use the linked Goethe official model exam and authentic recordings.","reading":[{"text":"Der Pullover kostet 25 Euro. Heute gibt es fünf Euro Rabatt.","question":"What is the discount?","choices":["5 euros","25 euros","10 euros"],"answer":0},{"text":"Heute sind alle blauen Jacken 20 Prozent günstiger.","question":"Which clothing is discounted?","choices":["Black shoes","Blue jackets","Red trousers"],"answer":1},{"text":"Lisa arbeitet von acht bis sechzehn Uhr. Danach geht sie nach Hause.","question":"When does Lisa finish work?","choices":["08:00","18:00","16:00"],"answer":2},{"text":"Die Mutter ruft ihren Sohn um acht Uhr an.","question":"When does the mother call?","choices":["08:00","18:00","07:00"],"answer":0},{"text":"Liebe Sara, wir treffen uns am Freitag um 18 Uhr im Park.","question":"Where is the meeting?","choices":["At the station","In the park","At a café"],"answer":1},{"text":"Der Bus 12 fährt zum Bahnhof. Er hält vor der Schule.","question":"Which bus goes to the station?","choices":["21","2","12"],"answer":2},{"text":"Die Apotheke ist neben der Bank. Sie öffnet um 9 Uhr.","question":"What is beside the bank?","choices":["Pharmacy","School","Hospital"],"answer":0},{"text":"Die Praxis ist heute bis 16 Uhr geöffnet. Morgen ist sie geschlossen.","question":"Until when is the office open?","choices":["18:00","16:00","12:00"],"answer":1},{"text":"Am Samstag ist es sonnig. Am Sonntag regnet es stark.","question":"What is Saturday’s weather?","choices":["Rainy","Snowy","Sunny"],"answer":2},{"text":"Max geht samstags ins Kino. Sonntags liest er zu Hause.","question":"What does Max do on Sunday?","choices":["Read at home","Go to cinema","Go swimming"],"answer":0},{"text":"Bibliothek: Montag–Freitag 9–18 Uhr. Samstag 10–14 Uhr. Sonntag geschlossen.","question":"When can you visit on Saturday?","choices":["09:00–18:00","10:00–14:00","The library is closed"],"answer":1},{"text":"Hallo Lena, ich komme heute später. Der Zug hat 30 Minuten Verspätung. Bis bald! — Tim","question":"Why will Tim arrive late?","choices":["His train is delayed","He is ill","He lost his phone"],"answer":0}],"listening":[{"text":"Ich wohne im zweiten Stock. Die Küche ist klein.","question":"What is small?","choices":["The balcony","The garden","The kitchen"],"answer":2},{"text":"Die Lampe ist neu, aber der Tisch ist alt.","question":"Which object is new?","choices":["The lamp","The table","The window"],"answer":0},{"text":"Ich spiele Fußball. Meine Schwester spielt Tennis.","question":"What does the speaker play?","choices":["Tennis","Football","Basketball"],"answer":1},{"text":"Ich habe zwei Kinder. Meine Kinder sind sechs und acht Jahre alt.","question":"How many children?","choices":["Three","One","Two"],"answer":2},{"text":"Wo wohnen Sie? – Ich wohne in Köln.","question":"What information was requested?","choices":["Place of residence","Age","Name"],"answer":0},{"text":"Haben Sie Milch? – Nein, leider haben wir keine Milch.","question":"What is unavailable?","choices":["Bread","Milk","Tea"],"answer":1},{"text":"Möchten Sie Wasser oder Saft? – Wasser, bitte.","question":"What is ordered?","choices":["Juice","Coffee","Water"],"answer":2},{"text":"Ich nehme die Suppe. Und zum Trinken ein Wasser, bitte.","question":"What food is ordered?","choices":["Soup","Salad","Bread"],"answer":0},{"text":"Entschuldigung, was kostet das Brot? – Zwei Euro fünfzig.","question":"How much is the bread?","choices":["€5.20","€2.50","€3.00"],"answer":1},{"text":"Ich brauche Schuhe in Größe 42. Haben Sie schwarze Schuhe?","question":"What color is requested?","choices":["Blue","Red","Black"],"answer":2},{"text":"Achtung! Der Zug nach Berlin fährt heute von Gleis fünf ab.","question":"Which platform is announced?","choices":["Platform 4","Platform 6","Platform 5"],"answer":2},{"text":"Guten Tag, hier ist die Praxis Müller. Ihr Termin ist am Dienstag um zehn Uhr.","question":"When is the appointment?","choices":["Tuesday at ten","Thursday at ten","Tuesday at twelve"],"answer":0}],"writing":[{"prompt":"Form practice: complete Vorname, Nachname, Wohnort and Sprache using fictional information.","model":"Vorname: Maya\nNachname: Thapa\nWohnort: Bonn\nSprache: Nepali"},{"prompt":"A friend invites you to a party. Write a short message: thank them, say you can come, and ask what time it starts.","model":"Liebe Anna,\nvielen Dank für die Einladung! Ich komme gern. Um wie viel Uhr beginnt die Party?\nLiebe Grüße\nMaya"},{"prompt":"Write a short email to your German course: explain you cannot come tomorrow, apologize and ask for the homework.","model":"Guten Tag,\nleider kann ich morgen nicht zum Deutschkurs kommen. Ich bin krank. Entschuldigung. Können Sie mir bitte die Hausaufgaben schicken?\nViele Grüße\nMaya"}],"speaking":[{"prompt":"Introduce yourself: name, country, town, languages and one hobby.","model":"Ich heiße Maya Thapa. Ich komme aus Nepal und wohne in Bonn. Ich spreche Nepali und ein bisschen Deutsch. Ich lese gern."},{"prompt":"Ask your partner a simple question about shopping, time or hobbies; then answer a similar question.","model":"Wo kaufen Sie Brot? — Ich kaufe Brot im Supermarkt."},{"prompt":"Make a polite request for a pen or a glass of water, then respond politely.","model":"Können Sie mir bitte einen Stift geben? — Ja, gern. Hier, bitte."}]},"sources":[{"title":"Goethe-Zertifikat A1: Start Deutsch 1 — exam description","url":"https://www.goethe.de/ins/de/en/prf/gzsd1.cfm"},{"title":"Goethe-Institut — A1 official practice materials & vocabulary list","url":"https://www.goethe.de/en/spr/prf/ueb/pa1.html"},{"title":"Council of Europe — CEFR A1 descriptors","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/cefr-descriptors-search"}]};
